    read_cdp_events_output: {
      type: "object",
      properties: {
        contract_version: {
          const: "5"
        },
        disposition: {
          enum: [
            "complete",
            "recovery_required",
            "rejected"
          ]
        },
        observed_at: {
          $ref: "#/$defs/timestamp"
        },
        caller: {
          $ref: "#/$defs/caller"
        },
        problem: {
          oneOf: [
            {
              $ref: "#/$defs/problem"
            },
            {
              type: "null"
            }
          ]
        },
        facts: {
          oneOf: [
            {
              $ref: "#/$defs/cdp_event_page"
            },
            {
              $ref: "#/$defs/event_recovery_facts"
            },
            {
              type: "null"
            }
          ]
        },
        available_actions: {
          type: "array",
          items: {
            $ref: "#/$defs/available_action"
          }
        }
      },
      required: [
        "contract_version",
        "disposition",
        "observed_at",
        "caller",
        "problem",
        "facts",
        "available_actions"
      ],
      additionalProperties: false,
      allOf: [
        {
          if: {
            properties: {
              disposition: {
                const: "complete"
              }
            },
            required: [
              "disposition"
            ]
          },
          then: {
            properties: {
              problem: {
                type: "null"
              },
              facts: {
                $ref: "#/$defs/cdp_event_page"
              }
            }
          }
        },
        {
          if: {
            properties: {
              disposition: {
                const: "recovery_required"
              }
            },
            required: [
              "disposition"
            ]
          },
          then: {
            properties: {
              problem: {
                type: "null"
              },
              facts: {
                $ref: "#/$defs/event_recovery_facts"
              }
            }
          }
        },
        {
          if: {
            properties: {
              disposition: {
                const: "rejected"
              }
            },
            required: [
              "disposition"
            ]
          },
          then: {
            properties: {
              problem: {
                $ref: "#/$defs/problem"
              },
              facts: {
                type: "null"
              }
            }
          }
        }
      ]
    },
